208	// TestDestroyConservationUsesChildInitialOnly 核对只认各直接子样创建时
209	// 取得的初始量：
210	//   - 子样后来继续分装、当前只剩 1.000，父样有缺口时仍按子样初始 4.000
211	//     计缺口（5.000+4.000=9.000，缺 1.000），不能改用子样当前剩余量；
212	//   - 孙样不重复计入，也不替父样凑数；
213	//   - 数量恰好守恒时（6.000+4.000=10.000），即使子样已把自己的量继续
214	//     分出或独立销毁，父样仍正常销毁 6.000，重开后可查询。
215	func TestDestroyConservationUsesChildInitialOnly(t *testing.T) {
216		// 场景一：子样 C 自身又分出 3.000 给孙样 G、当前只剩 1.000；父样剩余
217		// 5.000 有 1.000 缺口。直接分出总量必须仍显示 4.000、缺口 1.000。
218		childSplit := plainChild("C", "P", 4000, 1000)
219		childSplit.Children = []string{"G"}
220		childSplit.History = append(childSplit.History, historyRecord{
221			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
222		})
223		bad := &ledger{
224			Samples: map[string]*sampleRecord{
225				"P": withChild(activeSample("P", "", 10000, 5000), "C"),
226				"C": childSplit,
227				"G": plainChild("G", "C", 3000, 3000),
228			},
229		}
230		s, path := openGapLedger(t, bad)
231		_, err := s.Destroy(DestroyInput{
232			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
233		})
234		if !errors.Is(err, ErrConflict) {
235			t.Fatalf("按子样当前剩余量会误判缺口，仍应按其创建初始量拒绝: %v", err)
236		}
237		for _, want := range []string{"P", "5.000", "4.000", "1.000"} {
238			if !strings.Contains(err.Error(), want) {
239				t.Fatalf("错误说明应包含 %q（按子样创建初始量核对）: %v", want, err)
240			}
241		}
242		assertStillOpenAndUndestroyed(t, path, "P", "5.000", []string{"C"})
243	
244		// 场景二：父样剩余 6.000 恰好守恒，子样已分装用尽（无销毁信息）、
245		// 孙样持有全部 4.000；父样销毁成功，销毁量 6.000，重开可查询。
246		childExhausted := plainChild("C", "P", 4000, 0)
247		childExhausted.Children = []string{"G"}
248		childExhausted.History = append(childExhausted.History, historyRecord{
249			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
250		})
251		good1 := &ledger{
252			Samples: map[string]*sampleRecord{
253				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
254				"C": childExhausted,
255				"G": plainChild("G", "C", 4000, 4000),
256			},
257		}
258		s1, path1 := openGapLedger(t, good1)
259		view, err := s1.Destroy(DestroyInput{
260			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
261		})
262		if err != nil {
263			t.Fatalf("孙样不重复计入，6.000+4.000=10.000 应销毁成功: %v", err)
264		}
265		if view.Destruction == nil || view.Destruction.Qty != "6.000" || view.Remaining != "0.000" {
266			t.Fatalf("父样销毁视图错误: %+v", view)
267		}
268		reopened, err := Open(path1)
269		if err != nil {
270			t.Fatalf("守恒销毁后的文件必须仍能重新打开（这正是修复点）: %v", err)
271		}
272		p, _ := reopened.GetSample("P")
273		if p.Destruction == nil || p.Destruction.Qty != "6.000" || p.Remaining != "0.000" {
274			t.Fatalf("重开后销毁记录应保留真实销毁量 6.000: %+v", p)
275		}
276	
277		// 场景三：子样 C 已独立销毁 3.000（另分出 1.000 给孙样），父样仍按
278		// 子样创建初始量 4.000 核对，6.000+4.000=10.000 销毁成功。
279		childDestroyed := destroyedSampleWithParent("C", "P", 4000, 3000)
280		childDestroyed.Children = []string{"G"}
281		good2 := &ledger{
282			Samples: map[string]*sampleRecord{
283				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
284				"C": childDestroyed,
285				"G": plainChild("G", "C", 1000, 1000),
286			},
287		}
288		s2, path2 := openGapLedger(t, good2)
289		if _, err := s2.Destroy(DestroyInput{
290			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
291		}); err != nil {
292			t.Fatalf("子样后来销毁不改变父样已分出量，数量守恒应销毁成功: %v", err)
293		}
294		reopened2, err := Open(path2)
295		if err != nil {
296			t.Fatalf("父子各自销毁的守恒文件应正常重开: %v", err)
297		}
298		p2, _ := reopened2.GetSample("P")
299		c2, _ := reopened2.GetSample("C")
300		if p2.Destruction == nil || p2.Destruction.Qty != "6.000" {
301			t.Fatalf("父样销毁量应为 6.000: %+v", p2.Destruction)
302		}
303		if c2.Destruction == nil || c2.Destruction.Qty != "3.000" {
304			t.Fatalf("子样销毁记录应独立保留 3.000: %+v", c2.Destruction)
305		}
