463	// TestDestroyRejectsInconsistentChildRelationship 销毁不仅核对数量，还要求
464	// 子样列表与来源编号关系一致：旧文件若漏列真正的直接子样、重复列入或列入
465	// 来源不符的样品，即使数量等式碰巧成立，销毁也必须拒绝——否则销毁后的
466	// 文件会在重新打开时因来源关系自相矛盾而失败。拒绝后记录与文件保持原样。
467	func TestDestroyRejectsInconsistentChildRelationship(t *testing.T) {
468		// 漏列：C 的来源指向 P，P 的子样列表为空；剩余 6.000 + C 的 4.000
469		// 数量守恒，但漏列必须拒绝。
470		missing := &ledger{
471			Samples: map[string]*sampleRecord{
472				"P": activeSample("P", "", 10000, 6000),
473				"C": plainChild("C", "P", 4000, 4000),
474			},
475		}
476		s, path := openGapLedger(t, missing)
477		if _, err := s.Destroy(DestroyInput{
478			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
479		}); !errors.Is(err, ErrConflict) {
480			t.Fatalf("漏列直接子样时销毁应 ErrConflict, got %v", err)
481		}
482		assertStillOpenAndUndestroyed(t, path, "P", "6.000", nil)
483	
484		// 重复列入：C 在列表中出现两次（JSON 数组允许重复）。
485		dup := &ledger{
486			Samples: map[string]*sampleRecord{
487				"P": withChild(activeSample("P", "", 10000, 6000), "C", "C"),
488				"C": plainChild("C", "P", 4000, 4000),
489			},
490		}
491		s2, path2 := openGapLedger(t, dup)
492		_, err := s2.Destroy(DestroyInput{
493			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
494		})
495		if !errors.Is(err, ErrConflict) || !strings.Contains(err.Error(), "重复") {
496			t.Fatalf("重复列入子样应 ErrConflict 并说明重复, got %v", err)
497		}
498		assertStillOpenAndUndestroyed(t, path2, "P", "6.000", []string{"C", "C"})
499	
500		// 来源不符：列表列入的 R 是没有来源的原样。
501		wrong := &ledger{
502			Samples: map[string]*sampleRecord{
503				"P": withChild(activeSample("P", "", 10000, 6000), "R"),
504				"R": plainChild("R", "", 4000, 4000),
505			},
506		}
507		s3, path3 := openGapLedger(t, wrong)
508		_, err = s3.Destroy(DestroyInput{
509			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
510		})
511		if !errors.Is(err, ErrConflict) || !strings.Contains(err.Error(), "R") {
512			t.Fatalf("列入来源不符的样品应 ErrConflict 并指出编号, got %v", err)
513		}
514		assertStillOpenAndUndestroyed(t, path3, "P", "6.000", []string{"R"})
515	}
516

