293			t.Fatalf("上限父样恢复不精确: %+v", big)
294		}
295		bigC, _ := s.GetSample("BIG-C")
296		if bigC.InitialQty != belowMaxString {
297			t.Fatalf("上限附近子样恢复不精确: %s", bigC.InitialQty)
298		}
299	
300		overflow := &ledger{
301			Samples: map[string]*sampleRecord{
302				"BIG":   withChild(activeSample("BIG", "", maxUnits, maxUnits), "BIG-C"),
303				"BIG-C": plainChild("BIG-C", "BIG", 1, 1),
304			},
305		}
306		mustRejectOpen(t, writeStructLedger(t, overflow), "BIG", "超出可表示范围")
307	}
308

