func validateDestroyConservation(sampleID string, rec *sampleRecord, l *ledger) error {
	// 先核对子样列表与来源编号的关系一致，再统计直接分出总量，保证销毁
	// 落盘后的记录能通过重新打开时的来源关系与数量守恒核对。核对本身在
